from collections import defaultdict

def check_graph(edges, n=9):
    # Build adjacency
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check degree constraints
    degrees = [len(adj[i]) for i in range(n)]
    if min(degrees) < 2:
        return False, f"Min degree {min(degrees)} < 2"
    if max(degrees) > 3:
        return False, f"Max degree {max(degrees)} > 3"

    # Check edge count
    if len(edges) < 9 or len(edges) > 18:
        return False, f"Edge count {len(edges)} not in [9,18]"

    return True, "OK"

def greedy_chromatic(edges, n=9):
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    color = {}
    for node in range(n):
        neighbor_colors = {color[nb] for nb in adj[node] if nb in color}
        for c in range(1, n+1):
            if c not in neighbor_colors:
                color[node] = c
                break
    return max(color.values())

def chromatic_number(edges, n=9):
