    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Try k-coloring from k=2 upward
    def can_color(k):
        colors = [0] * n
        def backtrack(node):
            if node == n:
                return True
            neighbor_cols = {colors[nb] for nb in adj[node]}
            for c in range(1, k+1):
                if c not in neighbor_cols:
                    colors[node] = c
                    if backtrack(node + 1):
                        return True
                    colors[node] = 0
            return False
        return backtrack(0)

